def unit_of_work(metadata=None, timeout=None):
    """A decorator for transaction functions that allows extra control over how the transaction is carried out.
    It can specify metadata to be attached to the executing transaction and it can also specify a timeout for the transaction.

    :param metadata: A dictionary with metadata that will be attached to the executing transaction.
    :type metadata: dict
    :param timeout: The transaction timeout in seconds. If specified, overrides the default timeout set in the database.
    :type timeout: float or :const:`None`
    """
    def wrapper(fn):
        @functools.wraps(fn)
        def wrapped(*args, **kwargs):
            with Transaction(metadata=metadata, timeout=timeout) as tx:
                return fn(tx, *args, **kwargs)
        return wrapped
    return wrapper

