def round_half_to_even(n):
    """
    Round a given number to the nearest even integer.

    :param n: The number to round.
    :return: The rounded number.
    """
    # Check if the number is already an integer
    if n % 1 == 0:
        return n

    # Check if the number is halfway between two integers
    if n % 1 == 0.5:
        # Round the number to the nearest even integer
        if n % 2 == 0:
            return int(n)
        else:
            return int(n) + 1

    # The number is not halfway between two integers, so round it to the nearest integer
    return int(round(n))

