def _inline_r_setup(code: str) -> str:
    """
    Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    # Set R options
    r_options = code.split(" ")
    for option in r_options:
        try:
            option_name, option_value = option.split("=")
            option_name = option_name.lower()
            if option_name == "r_script":
                # Set the R script path
                with open(option_value, "r") as f:
                    code = f.read()
            elif option_name == "r_args":
                # Set the R arguments
                r_args = option_value.split(",")
                code = "\n".join([code, "# **** R ARGS ****\n"])
                for arg in r_args:
                    code += f"{arg}\n"
            elif option_name == "r_lib":
                # Set the R library path
                r_lib_path = option_value
                code = f"# **** R LIBRARY PATH ****\n{r_lib_path}\n\n{code}"
            else:
                print(f"Warning: unknown R option '{option_name}'")
        except ValueError:
            print(f"Warning: cannot parse R option '{option}'")
    return code

def xargs(cmd, varargs, *, color=False, target_concurrency=1, _max_length=_get_platform_max_length(), **kwargs):
    """A simplified implementation of xargs.

    Color: Make a pty if on a platform that supports it
    Target_concurrency: Target number of partitions to run concurrently
    """
    if not isinstance(cmd, tuple):
        raise TypeError("cmd must be a tuple")
    if not isinstance(varargs, Sequence):
        raise TypeError("varargs must be a Sequence")
    if not isinstance(color, bool):
        raise TypeError("color must be a bool")
    if not isinstance(target_concurrency, int):
        raise TypeError("target_concurrency must be an int")
    if not isinstance(_max_length, int):
        raise TypeError("_max_length must be an int")
    if not isinstance(kwargs, dict):
        raise TypeError("kwargs must be a dict")

    if len(cmd) < 1:
        raise ValueError("cmd must have at least one element")
    if len(varargs) < 1:
        raise ValueError("varargs must have at least one element")
    if target_concurrency < 1:
        raise ValueError("target_concurrency must be positive")
    if _max_length < 1:
        raise ValueError("_max_length must be positive")

    # Create a list of command line arguments
    cmd_args = [str(arg) for arg in cmd]
    varargs_args = [str(arg) for arg in varargs]

    # Check if a pty is needed
    if color and platform.system() in {"Linux", "Darwin"}:
        cmd_args.append("-pty")

    # Create a list of partitioned varargs
    partitioned_varargs = list(_partition(varargs_args, target_concurrency))

    # Iterate over the partitions and run the command
    for i, partition in enumerate(partitioned_varargs):
        # Join the partition with the command line arguments
        args = cmd_args + partition
        # Run the command with the partitioned varargs
        run_result = run(args, check=True, **kwargs)
        yield (i, run_result.returncode, run_result.stdout, run_result.stderr)

