    partitions = [partition for partition in _get_unique_partitions(varargs) if partition.length > 0]
    if not partitions:
        return 0, b""

    partition_idxs = range(len(partitions))
    partition_len = len(partitions[0])
    results: List[Optional[bytes]] = [None] * len(partitions)
    lock = threading.Lock()
    pool = concurrent.futures.ThreadPoolExecutor(max_workers=target_concurrency)
    futures = []

    def do_partition(idx: int) -> None:
        nonlocal lock, pool, results
        with lock:
            partition = partitions[idx]
            res = run(cmd, *partition, _max_length=_max_length, **kwargs)
            results[idx] = res

    for idx in partition_idxs:
        futures.append(pool.submit(do_partition, idx))

    for future in concurrent.futures.as_completed(futures):
        future.result()

    # Handle exceptions
    exceptions = []
    for idx, result in enumerate(results):
        if isinstance(result, Exception):
            exceptions.append((idx, result))
    if exceptions:
        raise XargsException(exceptions)

    # Print output
    if color:
        print(_get_colored_output(results))
    else:
        print(_get_output(results))

    return 0, b""

