        support."""
        cache = {}
        def _wrapper(*args, **kwargs):
            # Step 1: tries to get the value from the cache
            try:
                value = cache[args]
                if timer() - value[1] > ttl:
                    value = func(*args, **kwargs)
                    cache[args] = (value, timer())
                return value
            except KeyError:
                pass
            # Step 2: if the value does not exist in the cache, compute it and store it
            else:
                cache[args] = (func(*args, **kwargs), timer())
                return cache[args][0]
            # Step 3: clean up the cache by evicting the least recently used items
            cache_keys = list(cache.keys())
            cache_keys.remove(args)
            for key in cache_keys:
                if timer() - cache[key][1] > ttl:
                    del cache[key]
        return _wrapper
    return _ttl_cache

