def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Step 1: Sort the list of base classes by the number of classes they inherit from
    sorted_classes = sorted(classes, key=lambda x: len(x.get_ancestors()))

    # Step 2: Iterate over the sorted list and remove any base classes that are subclasses of previous base classes
    minimal_classes = []
    for base_class in sorted_classes:
        if not any(issubclass(base_class, minimal_class) for minimal_class in minimal_classes):
            minimal_classes.append(base_class)

    return minimal_classes

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes or not isinstance(classes, list):
        raise ValueError("'classes' must be a non-empty list")
    if len(classes) == 1:
        return classes

    ordered_classes = []
    for cls in classes:
        if cls not in ordered_classes:
            ordered_classes.append(cls)

    return ordered_classes

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Step 1: Sort the list of base classes in ascending order
    classes.sort()
    # Step 2: Iterate over the sorted list and remove any base classes that are already inherited by another base class
    for i in range(len(classes)):
        if classes[i] in [c.bases for c in classes if c.name != classes[i].name]:
            classes.remove(classes[i])
    # Step 3: Return the list of base classes in the same order they were provided
    return classes

