def _update_context(self, context):
    if not hasattr(context, "error"):
        context.error = []

    if hasattr(self, "E") and self.E is not None:
        context.error.append({"E": {"index": 0}})

    if hasattr(self, "t") and self.t is not None:
        context.error.append({"t": {"index": 1}})

    if hasattr(self, "error_E_low") and self.error_E_low is not None:
        context.error.append({"x_low": {"index": 2}})

    if hasattr(context, "value"):
        for key in context.value:
            if key not in context.error:
                del context.value[key]

    return context

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    try:
        if len(bins) != len(edges) - 1:
            raise ValueError("Invalid input: length of bins must be equal to length of edges - 1")
        h = np.diff(edges)
        return np.sum(bins * h)
    except:
        raise ValueError("Invalid input: edges must be monotonically increasing and contain at least one element")

