def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    try:
        if coord in self.bins:
            self.bins[coord] += weight
    except KeyError:
        pass
    except TypeError:
        raise TypeError("Invalid coordinate type")

def fill(self, coord, weight=1):
    """
    Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not (0 <= coord[0] < self.nx and 0 <= coord[1] < self.ny):
        raise ValueError(f"Coordinates {coord} are outside the histogram edges")

    if weight > 0:
        self.data[coord[0], coord[1]] += weight
    else:
        raise ValueError(f"Weight {weight} must be positive")

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if not isinstance(coord, tuple):
        raise TypeError("Coordinate must be a tuple")
    if len(coord) != self.dim:
        raise ValueError("Coordinate must have the same dimension as the histogram")
    if any(i < 0 or i >= self.bins for i in coord):
        raise ValueError("Coordinate must be within the histogram edges")
    self.weights[tuple(coord)] += weight

def _validate_labels(labels):
    errors = []
    for key, value in labels.items():
        try:
            if not re.match(r"^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)*$", key):
                errors.append({key: f"Label key '{key}' does not match the regex {r'^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)*$'}"})
            if not isinstance(value, (str, bytes)):
                errors.append({key: "expected string or bytes-like object"})
        except TypeError:
            errors.append({key: "expected string or bytes-like object"})
    if errors:
        raise ValidationError("\n".join([f"{err_dict[list(err_dict.keys())[0]]} ({list(err_dict.keys())[0]})" for err_dict in errors]))

def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    try:
        if not re.search(r"^[a-zA-Z0-9_-]+$", value):
            raise ValidationError("Invalid value: {}".format(value))
    except ValidationError as e:
        raise e
    else:
        return "Value is valid: {}".format(value)

