def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Generate a partial default observer schema dictionary from a Kubernetes resource manifest dictionary.

    Args:
        manifest_dict (dict): Partial Kubernetes resource manifest dictionary.
        first_level (bool, optional): If True, indicates that the dictionary represents the complete observer schema of a Kubernetes resource.

    Returns:
        dict: Generated partial observer schema dictionary.
    """
    observer_schema_dict = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            observer_schema_dict[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            observer_schema_dict[key] = generate_default_observer_schema_dict(value[0])
        else:
            observer_schema_dict[key] = None

    if first_level:
        # Copy the values of identifying fields from the manifest file to the observer schema dictionary
        for key, value in manifest_dict.items():
            if key in ["kind", "apiVersion", "metadata"]:
                observer_schema_dict[key] = value

    return observer_schema_dict

