        if field not in last_applied_manifest:
            last_applied_manifest[field] = field_schema.get('default', None)
        if field not in response:
            continue
        if isinstance(field_schema, dict):
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field], field_schema, response[field])
        else:
            last_applied_manifest[field] = response[field]
