def generate_default_observer_schema(app: kd.Application) -> typing.Dict[str, typing. Any]:
    """Generate the default observer schema for each Kubernetes resource present
    in ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    try:
        manifest = json.loads(app.spec.manifest)
        return {
            resource_type: {
                "persistentVolume": typ.PersistentVolumefactory.create(**resource),
                "persistentVolumeClaim": typ.PersistentVolumeClaimfactory.create(**resource),
                "configMap": typ.ConfigMapfactory.create(**resource),
                "service": typ.Servicefactory.create(**resource),
                "deployment": typ.Deploymentfactory.create(**resource),
            } for resource_type, resource in manifest.items() if resource_type not in ("persistentVolumeClaim", "configMap", "service", "deployment")
        }
    except (json.JSONDecodeError, AttributeError):
        return {}

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Handle edge case where the application has no manifest
    if not hasattr(app, "spec") or not hasattr(app.spec, "manifest"):
        return None

    # Get the application's manifest
    manifest = app.spec.manifest

    # Iterate over the manifest's resources and generate default observer schemas
    # for each resource that does not already have a custom observer schema
    for resource in manifest:
        if resource["apiVersion"] == "v1" and resource["kind"] == "Pod":
            if not hasattr(resource, "observer_schema"):
                # Generate default observer schema for pod
                pod = resource
                observer_schema = {}
                for container in pod.containers:
                    observer_schema[container.name] = {"container_name": container.name}
                resource.observer_schema = observer_schema

    return app.spec.manifest

def generate_default_observer_schema(app: kubernetes.Application) -> None:
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.
    """
    # Check if the input is valid
    if not isinstance(app, kubernetes.Application):
        raise TypeError("Invalid input type. Must be a kubernetes.Application object")

    # Generate the default observer schema
    default_observer_schema = {}
    for resource in app.spec.manifest:
        if not isinstance(resource, kubernetes.Resource):
            raise TypeError(f"Invalid resource type in manifest {resource}")

        # Add the default observer schema for each resource
        default_observer_schema[resource.manifest_name] = {
            "observe": [
                {
                    "type": "resource-readiness",
                    "successLookup": "successful_readiness",
                    "failureLookup": "unsuccessful_readiness",
                },
                {
                    "type": "resource-execution",
                    "successLookup": "successful_execution",
                    "failureLookup": "unsuccessful_execution",
                },
            ]
        }

    # Set the default observer schema for the application
    app.spec.observer = default_observer_schema

def format(self, sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the in-style parameters.

    :param sql: The SQL query.
    :param params: The set of in-style parameters.
    :return: A tuple containing the formatted SQL query and the set of converted out-style parameters.
    """
    # Handle edge cases
    if not sql or not params:
        return sql, params

    # Check the parameter style
    if isinstance(params, dict):
        param_style = 'named'
    elif isinstance(params, list):
        param_style = 'positional'
    else:
        raise ValueError('Invalid parameter style.')

    # Convert the parameters
    if param_style == 'named':
        converted_params = {key: val for key, val in params.items()}
    else:
        converted_params = {i: val for i, val in enumerate(params)}

    # Format the SQL query
    formatted_sql = sql.format(**converted_params)

    return formatted_sql, converted_params[::-1]

def format(sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    """
    Convert the SQL query to use the out-style parameters instead of
    the in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -	The formatted SQL query (:class:`str` or :class:`bytes`).

    -	The set of converted out-style parameters (:class:`dict` or
    	:class:`list`).
    """
    in_style = SQLParams.in_style
    out_style = SQLParams.out_style

    if in_style not in {"qmark", "numeric", "named"}:
        raise ValueError(f"Invalid in_style: {in_style}")

    if in_style == "named":
        if not isinstance(params, Mapping):
            raise TypeError(f"params must be a Mapping, got {type(params)}")
        params = {k: v for k, v in params.items() if k in sql}
    elif in_style == "numeric":
        if not isinstance(params, Sequence):
            raise TypeError(f"params must be a Sequence, got {type(params)}")
        params = [v for v in params]

    if out_style == "qmark":
        params = {k: QuestionMarkParam(v) for k, v in params.items()}
    elif out_style == "numeric":
        params = [v for v in params]

    return sql.replace(in_style, out_style), params

def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    - *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
    contains the set of in-style parameters. It maps each parameter
    (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
    is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
    If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
    *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    - The formatted SQL query (:class:`str` or :class:`bytes`).

    - A :class:`list` containing each set of converted out-style
    parameters (:class:`dict` or :class:`list`).
    """
    # Validate input
    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be a string or bytes-like object")
    if not isinstance(many_params, collections.abc.Iterable):
        raise TypeError("many_params must be an iterable")
    for params in many_params:
        if not isinstance(params, (collections.abc.Mapping, collections.abc.Sequence)):
            raise TypeError("each in-style parameter must be a mapping or sequence")
        if isinstance(params, collections.abc.Mapping):
            for key, value in params.items():
                if not isinstance(key, (str, int)):
                    raise TypeError("each parameter name must be a string or integer")
                if not isinstance(value, (str, int)):
                    raise TypeError("each parameter value must be a string or integer")
        else:
            for value in params:
                if not isinstance(value, (str, int)):
                    raise TypeError("each parameter value must be a string or integer")

    # Create a new ParameterHandler instance
    param_handler = ParameterHandler()

    # Convert in-style parameters to out-style parameters
    for params in many_params:
        if isinstance(params, collections.abc.Mapping):
            params = {key: value for key, value in params.items()}
        else:
            params = list(params)
        param_handler.bindparams(params)

    # Format the SQL query
    sql = param_handler.format_query(sql)

    # Return the formatted SQL query and the out-style parameters
    return sql, param_handler.parameters

def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    """
    Convert the SQL query to use the out-style parameters instead of the
    in-style parameters.

    *sql* (:class:`str` or :class:`bytes`) is the SQL query.

    *many_params* (:class:`~collections.abc.Iterable`) contains each set
    of in-style parameters (*params*).

    -   *params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
        contains the set of in-style parameters. It maps each parameter
        (:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
        is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
        If :attr:`.SQLParams.in_style` is an ordinal parameter style. then
        *params* must be a :class:`~collections.abc.Sequence`.

    Returns a :class:`tuple` containing:

    -   The formatted SQL query (:class:`str` or :class:`bytes`).

    -   A :class:`list` containing each set of converted out-style
        parameters (:class:`dict` or :class:`list`).
    """
    if not isinstance(sql, (str, bytes)):
        raise TypeError("sql must be a str or bytes")
    if not isinstance(many_params, Iterable):
        raise TypeError("many_params must be an iterable")

    many_params_list = list(many_params)
    if not many_params_list:
        return (sql, [])

    first_params = many_params_list[0]
    if isinstance(first_params, Mapping):
        in_style = "named"
    elif isinstance(first_params, Sequence):
        in_style = "ordinal"
    else:
        raise TypeError("params must be a Mapping or Sequence")

    out_params_list = []
    for params in many_params_list:
        if isinstance(params, Mapping):
            out_params = {**params}
        elif isinstance(params, Sequence):
            out_params = [*params]
        else:
            raise TypeError("params must be a Mapping or Sequence")
        out_params_list.append(out_params)

    return (sql, out_params_list)

