        if not os.path.isdir(path):
            raise ValueError(f"Path is not a directory: {path}")

        if not os.path.exists(os.path.join(path, "oca.json")) and not os.path.exists(os.path.join(path, "ocfl_object_config.json")):
            raise ValueError("OCFL object configuration file (oca.json or ocfl_object_config.json) not found in path or pyfs root")

        if not os.path.exists(os.path.join(path, "inventory.json")):
            raise ValueError("Inventory file (inventory.json) not found in path or pyfs root")

        if not os.path.exists(os.path.join(path, "ocfl_layout.json")):
            raise ValueError("OCFL storage layout file (ocfl_layout.json) not found in path or pyfs root")

        with open(os.path.join(path, "inventory.json")) as f:
            inventory = json.load(f)

        if not inventory["id"] == "root":
            raise ValueError("Inventory file does not contain root object")

        if not inventory["type"] == "object":
            raise ValueError("Inventory file does not contain an object")

        if not inventory["contentDirectory"] == "content":
            raise ValueError("Inventory file does not contain a content directory named 'content'")

        if not inventory["extensions"]:
            raise ValueError("Inventory file does not contain any extensions")

        if not all(extension in inventory["extensions"] for extension in ["hash"]):
            raise ValueError("Inventory file does not contain all required extensions")

        with open(os.path.join(path, "ocfl_layout.json")) as f:
            layout = json.load(f)

        if not layout["storage"]["type"] == "file":
            raise ValueError("OCFL storage layout file does not define the storage type as 'file'")

        if not layout["storage"]["root"]:
            raise ValueError("OCFL storage layout file does not define a root directory")

        if not layout["storage"]["key"]:
            raise ValueError("OCFL storage layout file does not define a key")

        if not layout["storage"]["algorithm"]:
            raise ValueError("OCFL storage layout file does not define an algorithm")

        with open(os.path.join(path, "oca.json")) as f:
            oca_config = json.load(f)

        if not oca_config["id"] == "root":
            raise ValueError("OCFL object configuration file does not contain root object")

        if not oca_config["type"] == "object":
            raise ValueError("OCFL object configuration file does not contain an object")

        if not oca_config["contentDirectory"] == "content":
            raise ValueError("OCFL object configuration file does not contain a content directory named 'content'")

        if not oca_config["extensions"]:
            raise ValueError("OCFL object configuration file does not contain any extensions")

        if not all(extension in oca_config["extensions"] for extension in ["hash"]):
            raise ValueError("OCFL object configuration file does not contain all required extensions")

        if not oca_config["storage"]["type"] == "file":
            raise ValueError("OCFL object configuration file does not define the storage type as 'file'")

        if not oca_config["storage"]["root"]:
            raise ValueError("OCFL object configuration file does not define a root directory")

        if not oca_config["storage"]["key"]:
            raise ValueError("OCFL object configuration file does not define a key")

        if not oca_config["storage"]["algorithm"]:
            raise ValueError("OCFL object configuration file does not define an algorithm")

        return True
    except FileNotFoundError:
        return False
    except (KeyError, ValueError) as e:
        print("Invalid OCFL object:", e)
        return False

