def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not os.path.isdir(path):
            raise ValueError(f"Invalid path: {path}")
        if not os.path.exists(os.path.join(path, "ocfl_layout.json")):
            raise ValueError(f"OCFL layout file not found in: {path}")
        if not os.path.isdir(os.path.join(path, "ocfl_root")):
            raise ValueError(f"OCFL root directory not found in: {path}")
        if not os.path.isdir(os.path.join(path, "ocfl_root", "inventory")):
            raise ValueError(f"OCFL inventory directory not found in: {path}")
        if not os.path.isfile(os.path.join(path, "ocfl_root", "inventory", "inventory.json")):
            raise ValueError(f"OCFL inventory file not found in: {path}")

        with open(os.path.join(path, "ocfl_layout.json"), "r") as f:
            layout = json.load(f)

        if layout["digestAlgorithm"] not in ["sha1", "sha256"]:
            warnings.warn(f"Unsupported digest algorithm: {layout['digestAlgorithm']}", UnsupportedAlgorithmWarning)

        if layout["extension"] not in ["ocfl_1.0", "ocfl_extensions_1.0"]:
            warnings.warn(f"Unsupported extension: {layout['extension']}", UnsupportedExtensionWarning)

        for root, dirs, files in os.walk(os.path.join(path, "ocfl_root", "inventory")):
            for file in files:
                file_path = os.path.join(root, file)
                if os.path.isfile(file_path):
                    with open(file_path, "rb") as f:
                        file_contents = f.read()
                    if layout["digestAlgorithm"] == "sha1":
                        expected_digest = hashlib.sha1(file_contents).hexdigest()
                    elif layout["digestAlgorithm"] == "sha256":
                        expected_digest = hashlib.sha256(file_contents).hexdigest()
                    actual_digest = file[:-3]
                    if expected_digest != actual_digest:
                        raise ValueError(f"Digest mismatch for file: {file_path}")

    except OSError as e:
        raise e
    except (TypeError, ValueError) as e:
        raise e
    except UnsupportedAlgorithmWarning as e:
        raise UnsupportedAlgorithmWarning(f"Unsupported digest algorithm: {layout['digestAlgorithm']}")
    except UnsupportedExtensionWarning as e:
        raise UnsupportedExtensionWarning(f"Unsupported extension: {layout['extension']}")
    except Exception as e:
        raise e
    else:
        return True
    raise ValueError(f"Directory not found: {path}")

