        raise ValueError("Inventory description must be provided in the metadata.")

    if "spec_version" not in inventory:
        inventory["spec_version"] = self.spec_version

    if inventory["spec_version"] not in self.supported_versions:
        raise ValueError(f"Unsupported inventory specification version: {inventory['spec_version']}")

    return inventory

def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not inventory:
        return False
    if extract_spec_version:
        spec_version = self.spec_version
        if "type" in inventory and inventory["type"] in SPEC_VERSIONS:
            spec_version = SPEC_VERSIONS[inventory["type"]]
        if "version" in inventory and inventory["version"] is not None:
            spec_version = inventory["version"]
        if spec_version is None or spec_version not in SPEC_VERSIONS:
            return False
        self.spec_version = spec_version
    return self._validate_inventory(inventory)

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Step 1: Validate input
    if not isinstance(manifest_files, list) or not isinstance(digests_used, list):
        raise TypeError("Invalid input. Both arguments must be lists.")
    if any(not isinstance(x, str) for x in manifest_files):
        raise TypeError("Invalid input. Manifest files must be strings.")
    if any(not isinstance(x, str) for x in digests_used):
        raise TypeError("Invalid input. Digests used must be strings.")

    # Step 2: Create a set of all digests needed
    needed_digests = set()
    for manifest_file in manifest_files:
        needed_digests.update(manifest_file.split(","))

    # Step 3: Get the set of digests present in the manifest
    present_digests = set(digests_used)

    # Step 4: Check if all needed digests are present
    if needed_digests != present_digests:
        return False
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""

    # Check that all needed digests are present in the manifest
    for digest in digests_used:
        if digest not in manifest_files:
            raise ValueError(f"The digest {digest} is not present in the manifest")

    # Check that all present digests are used in the manifest
    for digest in manifest_files:
        if digest not in digests_used:
            raise ValueError(f"The digest {digest} is not used in the manifest")

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("Prior version is not an InventoryValidator object")
    if prior.inventory_id != self.inventory_id:
        raise ValueError("Prior version is not the same inventory as the current version")
    if prior.version >= self.version:
        raise ValueError("Prior version is not earlier than the current version")
    return True

def validate_as_prior_version(self, prior):
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator object")
    # Check that prior is a valid prior version of the current inventory object
    if prior.version > self.version:
        raise ValueError("prior version must be earlier than current version")
    # Check for changes in items
    for item, qty in self.items.items():
        if item not in prior.items:
            raise ValueError(f"item {item} not found in prior inventory")
        if qty != prior.items[item]:
            raise ValueError(f"quantity of item {item} has changed")
    # Check for changes in suppliers
    for supplier, qty in self.suppliers.items():
        if supplier not in prior.suppliers:
            raise ValueError(f"supplier {supplier} not found in prior inventory")
        if qty != prior.suppliers[supplier]:
            raise ValueError(f"quantity from supplier {supplier} has changed")

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    if not isinstance(prior, InventoryValidator):
        raise ValueError("prior is not an InventoryValidator object")

    if self.inventory_id != prior.inventory_id:
        raise ValueError("inventory_id mismatch between self and prior")

    if self.current_date < prior.current_date:
        raise ValueError("current_date must be greater than or equal to prior's")

    if self.items.keys() != prior.items.keys():
        raise ValueError("Item set mismatch between self and prior")

    for item_id, item_data in self.items.items():
        prior_item_data = prior.items.get(item_id)
        if prior_item_data is None:
            raise ValueError(f"Item {item_id} not found in prior inventory")
        if item_data['quantity'] != prior_item_data['quantity']:
            raise ValueError(f"Quantity mismatch for item {item_id}")
        if item_data['unit_price'] != prior_item_data['unit_price']:
            raise ValueError(f"Unit price mismatch for item {item_id}")

    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not isinstance(inventory, dict):
        raise TypeError("Inventory must be a dictionary")
    if not isinstance(version, str):
        raise TypeError("Version must be a string")
    if version not in inventory:
        raise ValueError("Version not found in inventory")

    logical_path_map = {}
    for file_name, file_info in inventory[version].items():
        logical_path = file_info["logical_path_in_state"]
        if logical_path not in logical_path_map:
            logical_path_map[logical_path] = set()
        logical_path_map[logical_path].add(file_name)

    return logical_path_map

def get_logical_path_map(inventory, version):
