    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    logical_path_map = {}
    for item in inventory:
        if item['version'] == version:
            logical_path = item['logical_path']
            content_files = item['content_files']
            logical_path_map[logical_path] = content_files
    return logical_path_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Step 1: Validate inputs
    if not isinstance(inventory, dict) or not all(isinstance(key, str) and isinstance(value, list) for key, value in inventory.items()):
        raise TypeError("'inventory' must be a dictionary with string keys and list values")
    if not isinstance(version, str):
        raise TypeError("'version' must be a string")

    # Step 2: Initialize empty dictionary to store the map
    logical_path_map = {}

    # Step 3: Iterate over each key in the inventory dictionary
    for key, value in inventory.items():
        # Step 3a: Check if the key is a valid logical path
        if not key.startswith("/") or not key.endswith("/"):
            raise ValueError("Invalid logical path: " + key)

        # Step 3b: Get the corresponding files for the logical path
        logical_path = key.replace("/", "")
        logical_path_files = set()
        for content_file in value:
            if not isinstance(content_file, str):
                raise TypeError("Content files must be strings")
            if content_file.startswith(logical_path) and content_file.endswith(".json"):
                logical_path_files.add(content_file)

        # Step 3c: Add the logical path and files to the map
        logical_path_map[logical_path] = logical_path_files

    # Step 4: Return the map
    return logical_path_map

