def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Calculate the indentation
    indentation = " " * indent
    # Initialize the output string
    output = ""
    # Iterate over the attributes of self
    for attr in self.__dict__:
        # If the attribute is a string or number, append it to the output string
        if isinstance(attr, (str, int)):
            output += f"{indentation}{attr}: {self.__dict__[attr]}\n"
        # Else, if the attribute is a list, append each item in the list to the output string
        elif isinstance(attr, list):
            for item in self.__dict__[attr]:
                output += f"{indentation}- {item}\n"
        # Else, if the attribute is a dict, append each key-value pair in the dict to the output string
        elif isinstance(attr, dict):
            for key, value in self.__dict__[attr].items():
                output += f"{indentation}{key}: {value}\n"
    # Return the output string
    return output.strip()

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    if debug:
        # Create a new string that represents the object
        obj_string = "{\n"
        for key, value in self.__dict__.items():
            obj_string += f"{key}: {value},\n"
        obj_string += "}"

        # Indent the string based on the `indent` parameter
        lines = obj_string.split("\n")
        for i, line in enumerate(lines):
            if i > 0:
                lines[i] = " " * indent + line
        obj_string = "\n".join(lines)

        return obj_string
    else:
        return self.__repr__()

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Step 1: Determine the type of self
    if isinstance(self, (list, tuple)):
        pretty_type = "list"
    elif isinstance(self, dict):
        pretty_type = "dict"
    else:
        pretty_type = "unknown"

    # Step 2: Handle edge cases
    if pretty_type == "unknown":
        return self.__repr__()

    # Step 3: Construct the output
    output = []
    if pretty_type == "list":
        for item in self:
            output.append(item.pretty())
    elif pretty_type == "dict":
        for key, value in self.items():
            output.append(f"{key.pretty()}: {value.pretty()}")
    output = "\n".join(output)

    # Step 4: Indent and format the output
    if indent > 0:
        output = "\n".join(f"{indent * ' '}{line}" for line in output.splitlines())
    if debug:
        output = f"[DEBUG] {output}"

    return output

