            elif expr.left.operator == "&" and expr.left.right.operator == "~":
                result.append(expr.right | expr.left.right.right)
            elif expr.left.operator == "&":
                result.append(expr.right)
    return result

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expressions
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_list = []
    for arg in args:
        if arg.startswith("(") and arg.endswith(")"):
            contents = arg[1:-1]
            splitted = contents.split("|")
            if len(splitted) == 2:
                first = splitted[0]
                second = splitted[1]
                if first == second:
                    new_list.append(first)
                elif first.startswith("~") and first[1:] == second:
                    new_list.append(second)
                elif second.startswith("~") and second[1:] == first:
                    new_list.append(first)
                else:
                    new_list.append(arg)
            else:
                new_list.append(arg)
        else:
            new_list.append(arg)
    return new_list

def absorb(self, args):
    result = []
    for expr in args:
        if isinstance(expr, tuple) and len(expr) == 2:
            op, operands = expr
            if op in ("&", "|"):
                absorb_operands = [absorb(operand) for operand in operands]
                if op == "&":
                    if any(operand == "false" for operand in absorb_operands):
                        result.append("false")
                    else:
                        result.extend([operand for operand in absorb_operands if operand != "true"])
                else:
                    if any(operand == "true" for operand in absorb_operands):
                        result.append("true")
                    else:
                        result.extend([operand for operand in absorb_operands if operand != "false"])
            else:
                result.append(expr)
        else:
            result.append(expr)
    return result

def absorb(self, args):
    # Check if the input args is a sequence of expressions
    if not isinstance(args, (list, tuple)):
        raise ValueError("args must be a sequence of expressions")

    # Check if the input expressions are valid
    for expr in args:
        if not is_expression(expr):
            raise ValueError("invalid expression: {}".format(expr))

    # Apply absorption and negative absorption
    result = []
    for expr in args:
        if is_absorbed(expr):
            continue
        if is_absorbed(expr[0]):
            result.append(expr)
        else:
            result.append(apply_absorption(expr))

    return result

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expressions
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    if not isinstance(args, (list, tuple)):
        raise ValueError("Argument must be a sequence of expressions")

    if len(args) < 2:
        raise ValueError("At least 2 expressions are required for absorption")

    result = []
    for i in range(len(args) - 1):
        expr1 = args[i]
        expr2 = args[i + 1]

        if expr1.op != expr2.op:
            raise ValueError(f"Operator mismatch: {expr1.op} and {expr2.op}")

        if expr1.op in ["|", "&"]:
            if expr1.op == "|" and expr2.op == "&":
                # Absorption
                result.append(expr1)
            elif expr1.op == "&" and expr2.op == "|":
                # Negative absorption
                result.append(expr1)
            else:
                raise ValueError(f"Unsupported operator combination: {expr1.op} and {expr2.op}")
        else:
            raise ValueError(f"Unsupported operator: {expr1.op}")

    return result

def on(self, hook):
    """Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.

    """
    def add_handler(func):
        if not hasattr(self, '_hook_registry'):
            self._hook_registry = {}
        if hook not in self._hook_registry:
            self._hook_registry[hook] = []
        self._hook_registry[hook].append(func)
        return func
    return add_handler

def on(self, hook: HookType) -> callable:
    def decorator(func: callable) -> callable:
        if hook not in self._registry:
            self._registry[hook] = []
        self._registry[hook].append(func)
        return func
    return decorator

