def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: A list of commands to execute.
    :param args: A list of arguments to pass to each command.
    :param cwd: The current working directory.
    :param verbose: Whether to print verbose output.
    :param hide_stderr: Whether to hide stderr.
    :param env: The environment variables to use.
    """
    if not commands:
        raise ValueError("No commands provided")

    for command in commands:
        if not isinstance(command, (list, tuple)):
            raise TypeError(f"Invalid command type: {type(command)}")
        if not command:
            raise ValueError("Empty command")

    if not args:
        raise ValueError("No arguments provided")
    if not isinstance(args, (list, tuple)):
        raise TypeError(f"Invalid arguments type: {type(args)}")

    if cwd is not None and not isinstance(cwd, str):
        raise TypeError(f"Invalid cwd type: {type(cwd)}")

    if not isinstance(verbose, bool):
        raise TypeError(f"Invalid verbose type: {type(verbose)}")

    if not isinstance(hide_stderr, bool):
        raise TypeError(f"Invalid hide_stderr type: {type(hide_stderr)}")

    if env is not None and not isinstance(env, dict):
        raise TypeError(f"Invalid env type: {type(env)}")

    for command in commands:
        command_str = " ".join(command)
        print(f"Running command: {command_str}")
        if cwd is not None:
            os.chdir(cwd)
        if env is not None:
            os.environ.update(env)
        result = subprocess.run(command_str, args, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if verbose:
            print(f"Return code: {result.returncode}")
            if not hide_stderr:
                print(f"Stderr output: {result.stderr.decode()}")
            print(f"Stdout output: {result.stdout.decode()}")
        yield result.returncode, result.stdout.decode(), result.stderr.decode()

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    try:
        if cwd is None:
            cwd = os.getcwd()
        if env is None:
            env = os.environ
        if isinstance(commands, str):
            commands = [commands]
        for command in commands:
            process = subprocess.Popen(command, args, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
            stdout, stderr = process.communicate()
            if hide_stderr:
                stderr = ""
            if verbose:
                print(f"Result of '{command}': {stdout.decode()}")
            yield stdout.decode(), stderr.decode()
    except FileNotFoundError:
        yield None, f"Command {command} not found"
    except subprocess.CalledProcessError as e:
        yield None, f"Command {command} failed with exit code {e.returncode}"

def run_command(commands: List[str], args: List[str], cwd: str = None, verbose: bool = False, hide_stderr: bool = False, env: Dict[str, str] = None) -> subprocess.CompletedProcess:
    """Call the given command(s)."""
    try:
        if cwd is None:
            cwd = os.getcwd()
        if env is None:
            env = os.environ.copy()
        if isinstance(commands, str):
            commands = [commands]
        if isinstance(args, str):
            args = [args]
        process = subprocess.Popen(commands + args, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if hide_stderr:
            process.communicate()[1]
        else:
            stdout, stderr = process.communicate()
            if verbose:
                print(stdout.decode())
                print(stderr.decode(), file=sys.stderr)
        return process.wait()
    except Exception as e:
        raise RuntimeError(f"Failed to run command: {commands} {args}") from e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not commands:
        raise ValueError("No command specified")

    if cwd is not None and not os.path.isdir(cwd):
        raise ValueError("Current working directory does not exist")

    if env is not None and not isinstance(env, dict):
        raise ValueError("Environment must be a dictionary")

    if hide_stderr and verbose:
        raise ValueError("Cannot hide stderr and be verbose at the same time")

    if env is not None:
        env.update(os.environ)

    if isinstance(commands, str):
        commands = [commands]

    for command in commands:
        if not command.strip():
