def register_vcs_handler(vcs, method):
    """
    Create decorator to mark a method as the handler of a VCS.

    :param vcs: The VCS to handle.
    :param method: The method to use as the handler.
    :return: A decorator that registers the method as the handler for the VCS.
    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if vcs not in VCS_HANDLERS:
                VCS_HANDLERS[vcs] = []
            VCS_HANDLERS[vcs].append(method)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    def wrapper(*args, **kwargs):
        try:
            result = method(*args, **kwargs)
            vcs.add_handler(method)
            return result
        except Exception as e:
            raise e
    return wrapper

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    for obj in self.objects.values():
        num_objects += 1
        if validate_objects:
            if not obj.validate():
                if show_warnings:
                    print(f"Object {obj.id} is invalid.")
                continue
        if check_digests:
            if not obj.digest:
                if show_warnings:
                    print(f"Object {obj.id} has no digest.")
                continue
            if not obj.validate_digest():
                if show_warnings:
                    print(f"Object {obj.id} has an invalid digest.")
                continue
        good_objects += 1
    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    if validate_objects:
        # Iterate over all objects in the storage root and validate them
        for object_hash in self.root_hashes:
            try:
                data = self.get_object(object_hash)
                good_objects += 1
            except KeyError:
                # If the object is not found, it is not a valid object
                pass
            num_objects += 1

        if num_objects == 0:
            raise ValueError("No objects found in storage root")

    if check_digests:
        # Validate the digests of all objects in the storage root
        for object_hash in self.root_hashes:
            try:
                data = self.get_object(object_hash)
                digest = self.get_digest(object_hash)
                if digest != data.digest:
                    raise ValueError("Digest mismatch for object {}".format(object_hash))
            except KeyError:
                # If the object is not found, it is not a valid object
                pass

    if num_objects != good_objects:
        raise ValueError("Invalid objects found in storage root")

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0

    # Check all directories under the storage root
    for path in os.listdir(self.root_path):
        if os.path.isdir(os.path.join(self.root_path, path)):
            # Check the directory for a ".meta" file
            meta_path = os.path.join(self.root_path, path, ".meta")
            if os.path.exists(meta_path):
                try:
                    meta_data = meta_path.read()
                    # Check the meta data for validity
                    if not self.validate_meta_data(meta_data):
                        if show_warnings:
                            print(f"WARNING: Invalid meta data for '{path}'")
                        continue

                    # Check the directory for matching object files
                    object_path = os.path.join(self.root_path, path, "object")
                    if not os.path.exists(object_path):
                        if show_warnings:
                            print(f"WARNING: Missing object file for '{path}'")
                    elif not os.path.isfile(object_path):
                        if show_warnings:
                            print(f"WARNING: Invalid object file for '{path}'")
                    else:
                        if check_digests:
                            try:
                                object_hash = object_path.compute_digest()
                                if object_hash != meta_data["digest"]:
                                    if show_warnings:
                                        print(f"WARNING: Object file digest mismatch for '{path}'")
                            except ValueError:
                                if show_warnings:
                                    print(f"WARNING: Invalid object file digest for '{path}'")
                        good_objects += 1
                except OSError as e:
                    if show_warnings:
                        print(f"WARNING: Error reading meta data for '{path}': {e}")
                #other files
                other_path = os.path.join(self.root_path, path, "other")
                if os.path.exists(other_path):
                    if show_warnings:
                        print(f"WARNING: Other files detected in '{path}'")
            num_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects = 0
    good_objects = 0
    for node in self.storage_root.iter_tree():
        try:
            if validate_objects:
                node.validate()
                num_objects += 1
                if node.valid:
                    good_objects += 1
            if check_digests:
                node.verify_digest()
        except (InvalidNodeError, DigestMismatchError) as e:
            if show_warnings:
                print(f"Warning: Invalid node {node.name}: {str(e)}")
    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Create the storage root directory if it doesn't exist
    if not os.path.exists(self.storage_root):
        os.makedirs(self.storage_root)

    # Initialize the object version and type maps
    self.object_versions = {}
    self.object_types = {}

    # Create the version/type directory structure
    for version in self.versions:
        for obj_type in self.types:
            version_type_dir = os.path.join(self.storage_root, version, obj_type)
            if not os.path.exists(version_type_dir):
                os.makedirs(version_type_dir)

    # Initialize the file and directory inventory
    self.inventory = {}

    # Add the inventory to the OCFL object
    self.object.add_inventory(self.inventory)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        version_parts = version.split('.')
        for i in range(len(version_parts)):
            if version_parts[i].startswith('0'):
                version_parts[i] = '1' + version_parts[i][1:]
            else:
                version_parts[i] = str(int(version_parts[i]) + 1)
        return '.'.join(version_parts)
    except:
        raise ValueError("Invalid version string")

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise ValueError("Version must be a string")
    if not re.match(r"\d+\.\d+\.\d+", version):
        raise ValueError("Version must be in the format 'X.Y.Z'")
    version_parts = version.split(".")
    next_version_parts = [str(int(version_part) + 1) for version_part in version_parts]
    return ".".join(next_version_parts)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    # Check if input is a valid version string
    if not is_valid_version(version):
        raise ValueError("Invalid version string")

    # Split version string into parts
    parts = version.split(".")

    # Check if major version is zero-prefixed
    if parts[0].startswith("0"):
        # Increment minor version
        parts[1] = str(int(parts[1]) + 1)
        return ".".join(parts)
    else:
        # Increment major version
        parts[0] = str(int(parts[0]) + 1)
        return ".".join(parts)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Check that each version has an inventory
    for version_dir in version_dirs:
        inventory_file = os.path.join(version_dir, 'inventory.json')
        if not os.path.isfile(inventory_file):
            raise Exception(f'Version {version_dir} is missing inventory file')

    # Compare the content digests in the inventory to the root inventory
    root_inventory_file = os.path.join(self.content_dir, 'inventory.json')
    with open(root_inventory_file, 'r') as f:
        root_inventory = json.load(f)

    for version_dir in version_dirs:
        inventory_file = os.path.join(version_dir, 'inventory.json')
        with open(inventory_file, 'r') as f:
            inventory = json.load(f)

        for digest in root_inventory['digests']:
            if digest not in inventory['digests']:
                raise Exception(f'Version {version_dir} is missing digest {digest}')

        for file_path in root_inventory['files']:
            if file_path not in inventory['files']:
                raise Exception(f'Version {version_dir} is missing file {file_path}')

def validate_version_inventories(self, version_dirs):
    """
    Check that each version directory contains a version inventory, and that the inventory
    is valid by comparing against the root inventory.

    version_dirs: list of version directory names
    """
    # Step 1: Get the root inventory and check if it is valid
    root_inventory = self.get_root_inventory()
    if not root_inventory:
        raise RuntimeError("No root inventory found!")

    # Step 2: Iterate through each version directory and check if it has a valid inventory
    for version_dir in version_dirs:
        inventory_file = os.path.join(version_dir, "inventory.json")
        if not os.path.exists(inventory_file):
            raise RuntimeError(f"Inventory file not found for version {version_dir}")

        with open(inventory_file, "r") as f:
            inventory = json.load(f)

        # Step 3: Check if the inventory is valid by comparing against the root inventory
        for file, digest in inventory.items():
            if file not in root_inventory or digest != root_inventory[file]:
                raise RuntimeError(f"Inventory mismatch for file {file} in version {version_dir}")

        # Step 4: Check if there are any unexpected files in the version directory
        for file in os.listdir(version_dir):
            if file not in inventory and not file.startswith("."):
                raise RuntimeError(f"Unexpected file {file} found in version {version_dir}")

        # Step 5: Check if there are any missing files in the version directory
        for file in inventory.keys():
            if not os.path.exists(os.path.join(version_dir, file)):
                raise RuntimeError(f"File {file} not found in version {version_dir}")

    # Step 6: If everything is valid, return True
    return True

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        file_list = os.listdir(path)
        for file in file_list:
            if file.startswith("0=*"):
                if file.endswith(".json"):
                    return "root"
                elif file.endswith(".txt"):
                    return "object"
                else:
                    return "file"
        return "unknown"
    except OSError:
        return "error"

