    '''
    Returns a string indicating the type of thing at the given path. Return values:
        'root': looks like an OCFL Storage Root
        'object': looks like an OCFL Object
        'file': a file, might be an inventory
        Any other string: error description
    Looks only at "0=*" Namaste files to determine the directory type.
    '''
    try:
        if path is None or not os.path.isfile(path):
            return 'error: invalid path'
        with open(path, 'rt') as f:
            for line in f:
                if line.startswith('0=*'):
                    if line.endswith('records'):
                        return 'root'
                    if line.endswith('={}.txt.json'):
                        return 'object'
                    if line.endswith('.json'):
                        return 'file'
    except Exception as e:
        return 'error: ' + str(e)
    return 'error: cannot determine directory type'

def find_path_type(path):
    '''Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    '''
    if not path.exists():
        return "Path does not exist."

    for namaste_file in path.get_children():
        matches = re.match(r'^0=.*', namaste_file.get_name())
        if matches:
            match = matches[0]
            if match == '0=ocfl_object':
                return 'object'
            elif match == '0=ocfl_root':
                return 'root'

    return 'file'

