    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    # Step 1: Create a dictionary to store the parsed arguments for each subparser
    parsed_arguments = {}

    # Step 2: Iterate over the unparsed arguments and try to parse them with each subparser
    for subparser_name, subparser in subparsers.items():
        # Step 2a: Check if the subparser has any remaining arguments to parse
        if len(unparsed_arguments) == 0:
            break

        # Step 2b: Try to parse the unparsed arguments with the current subparser
        try:
            parsed_arguments[subparser_name] = subparser.parse_args(unparsed_arguments)
        except argparse.ArgumentError:
            pass
        except Exception:
            raise

        # Step 2c: Remove the parsed arguments from the unparsed arguments list
        unparsed_arguments = [arg for arg in unparsed_arguments if arg not in parsed_arguments[subparser_name]]

    # Step 3: Check if all unparsed arguments have been claimed by a subparser
    if len(unparsed_arguments) > 0:
        raise argparse.ArgumentError("Unable to parse the following arguments: {}".format(", ".join(unparsed_arguments)))

    # Step 4: Return a tuple of the parsed arguments and the remaining unparsed arguments
    return (parsed_arguments, unparsed_arguments)

