    if number < 0:
        raise ValueError("The number parameter cannot be negative.")
    if len(alphabet) == 0:
        raise ValueError("The alphabet parameter cannot be empty.")
    if padding is not None and padding < 1:
        raise ValueError("The padding parameter must be at least 1.")

    if padding is None:
        padding = 1

    alphabet_length = len(alphabet)
    result = ""
    while number > 0:
        result = alphabet[(number % alphabet_length)] + result
        number //= alphabet_length

    if padding > len(result):
        result = "0" * (padding - len(result)) + result

    return result

