def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not string or not alphabet:
        raise ValueError("Both the string and alphabet must be provided")

    base = len(alphabet)
    number = 0
    for i, char in enumerate(string):
        try:
            digit = alphabet.index(char)
        except ValueError:
            raise ValueError(f"The character {char} is not in the alphabet")

        number += base ** i * digit

    return number

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not string or not alphabet:
        raise ValueError("Input string and alphabet must not be empty")
    if len(string) > len(alphabet):
        raise ValueError("Input string must not be longer than the alphabet")
    if not all(c in alphabet for c in string):
        raise ValueError("Input string must only contain characters from the alphabet")

    number = 0
    for i, char in enumerate(string):
        number += alphabet.index(char) * (len(alphabet) ** i)

    return number

