        raise ValueError("Invalid frequency: {}".format(frequency))
    if unit not in ["day", "days", "week", "weeks", "month", "months", "year", "years"]:
        raise ValueError("Invalid unit of time: {}".format(unit))
    if unit in ["day", "days"]:
        delta = datetime.timedelta(days=num)
    elif unit in ["week", "weeks"]:
        delta = datetime.timedelta(weeks=num)
    elif unit in ["month", "months"]:
        delta = datetime.timedelta(days=30 * num)
    elif unit in ["year", "years"]:
        delta = datetime.timedelta(days=365 * num)
    return delta

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    unit_to_seconds = {
        "seconds": 1,
        "minutes": 60,
        "hours": 3600,
        "days": 86400,
        "weeks": 604800,
        "months": 2628000,
        "years": 31536000
    }

    try:
        value, unit = frequency.split(" ")
        value = int(value)
        seconds = unit_to_seconds[unit.lower()]
        return datetime.timedelta(seconds=value * seconds)
    except ValueError:
        raise ValueError("Invalid frequency")
    except KeyError:
        raise ValueError("Invalid unit")

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        number, unit = frequency.split()
        number = int(number)
        if unit.lower() == "week":
            return datetime.timedelta(weeks=number)
        elif unit.lower() == "day":
            return datetime.timedelta(days=number)
        elif unit.lower() == "hour":
            return datetime.timedelta(hours=number)
        elif unit.lower() == "minute":
            return datetime.timedelta(minutes=number)
        else:
            raise ValueError(f"Invalid unit of time: {unit}")
    except ValueError:
        raise ValueError(f"Invalid frequency: {frequency}")

