def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    if overwrite or not os.path.exists(config_filename):
        try:
            os.makedirs(os.path.dirname(config_filename), exist_ok=True)
            with open(config_filename, 'w', encoding='utf8', mode) as f:
                f.write(rendered_config)
        except OSError as e:
            raise OSError(f'Failed to write configuration file {config_filename}: {e}')
    else:
        raise OSError(f'Configuration file {config_filename} already exists and overwrite is False')

def subprocess_run_helper(func: function, *args: str, timeout: int = 10, extra_env: dict[str, str] = None) -> CompletedProcess:
    """
    Run a function in a sub-process.

    Parameters
    ----------
    func : function
        The function to be run.  It must be in a module that is importable.
    *args : str
        Any additional command line arguments to be passed in
        the first argument to ``subprocess.run``.
    extra_env : dict[str, str]
        Any additional environment variables to be set for the subprocess.
    """
    if not callable(func):
        raise TypeError("func must be a callable function")
    if not isinstance(args, tuple):
        raise TypeError("args must be a tuple")
    if not isinstance(timeout, int):
        raise TypeError("timeout must be an integer")
    if (extra_env is not None) and not isinstance(extra_env, dict):
        raise TypeError("extra_env must be a dictionary")

    module_name = func.__module__
    func_name = func.__name__
    command = [module_name, func_name] + list(args)

    env = os.environ.copy()
    if extra_env is not None:
        env.update(extra_env)

    try:
        result = subprocess.run(command, timeout=timeout, check=True, env=env)
        return CompletedProcess(result.args, result.returncode, result.stdout, result.stderr, result.pid, result.timeout)
    except subprocess.CalledProcessError as e:
        return CompletedProcess(e.args, e.returncode, e.stdout, e.stderr, e.pid, e.timeout)
    except subprocess.TimeoutExpired:
        raise Exception("Timed out while running command") from None
    except Exception:
        raise Exception("Unable to run command") from None

def subprocess_run_helper(func, *args, timeout, extra_env=None):
    import subprocess

    if not callable(func):
        raise TypeError("func must be a callable function")

    if not isinstance(timeout, int) or timeout < 0:
        raise ValueError("timeout must be a positive integer")

    if not isinstance(extra_env, dict) and extra_env is not None:
        raise TypeError("extra_env must be a dictionary or None")

    env = os.environ.copy()
    if extra_env is not None:
        env.update(extra_env)

    try:
        result = subprocess.run([sys.executable, "-c", "import {func.__module__} as mod; mod.{func.__name__}()"] + list(args),
                    env=env, timeout=timeout,
                    stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except subprocess.TimeoutExpired:
        return "Timeout"
    except subprocess.CalledProcessError as e:
        return e.output.decode("utf-8")
    else:
        return result.stdout.decode("utf-8")

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    name, default = matcher.groups()

    if name not in os.environ and default is None:
        raise Error(f"Variable '{name}' is not defined in environment and no default value is provided")

    return os.environ.get(name, default)

def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    name, default = matcher.group(1), matcher.group(2)
    value = os.environ.get(name)
    if value is None:
        if default is None:
            raise Error(f"Environment variable {name} is not defined and no default value was provided.")
        else:
            value = default
    return value

