def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s).

    Args:
        commands: A list of commands to execute.
        args: A list of positional arguments to pass to the command.
        cwd: The current working directory for the command.
        verbose: If True, print the command and its output.
        hide_stderr: If True, hide the command's stderr output.
        env: The environment variables to use for the command.

    Returns:
        The exit code of the command.

    Raises:
        CalledProcessError: If the command exits with a non-zero exit code.
    """
    if commands is None or not isinstance(commands, list):
        raise TypeError("commands must be a list of strings")
    if args is None or not isinstance(args, list):
        raise TypeError("args must be a list of strings")
    if cwd is not None and not isinstance(cwd, str):
        raise TypeError("cwd must be a string")
    if env is not None and not isinstance(env, dict):
        raise TypeError("env must be a dictionary")

    for command in commands:
        if not isinstance(command, str):
            raise TypeError("commands must be strings")

    command_string = " ".join(commands)
    if args:
        command_string += " " + " ".join(args)

    if verbose:
        print(command_string)

    process = subprocess.Popen(command_string, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    stdout, stderr = process.communicate()

    if hide_stderr:
        stderr = ""

    if process.returncode != 0:
        raise CalledProcessError(process.returncode, command_string)

    if verbose:
        print(stdout.decode(), end="")
        if stderr:
            print(stderr.decode(), end="")

    return process.returncode

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    :param commands: A list of commands to run.
    :param args: A list of arguments to pass to each command.
    :param cwd: The current working directory to use for each command.
    :param verbose: Whether to display the output of the command.
    :param hide_stderr: Whether to hide the stderr output of the command.
    :param env: The environment variables to use for each command.
    :return: The return code of the command.
    """
    if not isinstance(commands, list):
        commands = [commands]
    for command in commands:
        if not isinstance(command, str):
            raise ValueError("Command must be a string")
        if not isinstance(args, list):
            raise ValueError("Arguments must be a list")
        if cwd is not None and not isinstance(cwd, str):
            raise ValueError("Current working directory must be a string")
        if not isinstance(verbose, bool):
            raise ValueError("Verbose must be a boolean")
        if not isinstance(hide_stderr, bool):
            raise ValueError("Hide stderr must be a boolean")
        if env is not None and not isinstance(env, dict):
            raise ValueError("Environment variables must be a dictionary")

    for command in commands:
        if verbose:
            print(f"Running command: {command}")
        try:
            result = subprocess.run(command, args, cwd=cwd, env=env, stderr=subprocess.PIPE)
        except OSError as e:
            print(f"Error running command: {e}")
            return -1
        if not hide_stderr and result.stderr:
            print(result.stderr.decode())
        return result.returncode

