def find_roots(graph: rdflib.Graph, prop: rdflib.URIRef, roots: Optional[Set[rdflib.Node]] = None) -> Set[rdflib.Node]:
    if not roots:
        roots = set()

    for triple in graph.triples((None, prop, None)):
        roots.add(triple[0])

    for triple in graph.triples((None, prop, None)):
        if triple[0] in roots:
            roots.discard(triple[2])

    return roots

