def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    # Determine the appropriate encoding based on the Python version
    if sys.version_info[0] < 3:
        encoding = "unicode-escape"
    else:
        encoding = "unicode"

    # Dump the object to a YAML document using the appropriate encoding
    try:
        yaml_doc = yaml.dump(obj, encoding=encoding, dumper=dumper)
    except yaml.YAMLError as e:
        raise ValueError("Failed to dump object to YAML document") from e

    # Convert the YAML document to a py2-unicode or py3-string
    try:
        yaml_string = yaml_doc.decode(encoding)
