def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    try:
        if protocol_version is None:
            return {version: handler for version, handler in cls.PROTOCOL_HANDLERS.items() if version >= cls.SUPPORTED_MIN_PROTOCOL}
        else:
            if type(protocol_version) is not tuple:
                raise TypeError("Protocol version must be passed in a tuple")
            elif cls.SUPPORTED_MIN_PROTOCOL > protocol_version[0]:
                raise ValueError("Unsupported protocol version")
            else:
                return {protocol_version: cls.PROTOCOL_HANDLERS.get(protocol_version)}
    except TypeError:
        raise TypeError("Protocol version must be passed in a tuple")
    except ValueError:
        raise ValueError("Unsupported protocol version")

def protocol_handlers(protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers, keyed by version tuple.
    If an explicit protocol version is provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol version is provided,
    all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    version_to_handler = {
        (3, 5): Bolt35ProtocolHandler,
        (4, 1): Bolt41ProtocolHandler,
        (4, 2): Bolt42ProtocolHandler,
        (4, 3): Bolt43ProtocolHandler,
        (4, 4): Bolt44ProtocolHandler,
    }

    if protocol_version is not None:
        if not isinstance(protocol_version, tuple):
            raise TypeError(f"Protocol version {protocol_version} must be passed in a tuple")
        handlers = {protocol_version: version_to_handler[protocol_version]}
    else:
        handlers = {version: version_to_handler[version] for version in version_to_handler}

    return handlers

def protocol_handlers(cls, protocol_version=None):
