def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None and not isinstance(explicit_mc, type):
        raise TypeError("__metaclass__ is not a type")
    if len(bases) == 0:
        raise TypeError("No bases to determine metaclass from")
    if len(bases) == 1:
        return bases[0]
    return type(bases[0], bases[1], {})

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    base_metas = set(type(base) for base in bases)
    if len(base_metas) == 1:
        return base_metas.pop()
    elif len(base_metas) == 0:
        return type
    else:
        return type(type.__name__, tuple(base_metas), {})

