    if explicit_mc is not None:
        return explicit_mc
    mcs = [getattr(b, '__class__', type) for b in bases]
    for mc in mcs:
        if issubclass(mc, type):
            return mc
    return type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    try:
        if explicit_mc is not None:
            return explicit_mc
        elif len(bases) == 1:
            return type(bases[0])
        else:
            metaclasses = set(type(base) for base in bases)
            if len(metaclasses) == 1:
                return metaclasses.pop()
            else:
                raise TypeError("Creating a class with more than one metaclass is not supported")
    except TypeError:
        raise TypeError("Cannot determine metaclass")

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    else:
        max_mro = bases[0].__mro__
        for base in bases:
            if len(base.__mro__) > len(max_mro):
                max_mro = base.__mro__
        return max_mro[0]

