    tags = set()
    text_tokens = text.split()
    for token in text_tokens:
        if token.startswith("{{") and token.endswith("}}"):
            tags.add(token[2:-2])
        elif replacer is not None and token.startswith("`") and token.endswith("`"):
            tags.add(replacer(token[1:-1]))
    return tags, text

