def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    try:
        # Tokenize the text into words
        words = text.split()
        # Iterate over the words and check if any of them are links
        for i, word in enumerate(words):
            if word.startswith("https://") or word.startswith("http://"):
                # If it's a link, add the necessary attributes and linkify it
                words[i] = f'<a href="{word}" target="_blank" rel="noreferrer noopener">{word}</a>'
        # Join the modified words back into a single string
        text = " ".join(words)
    except:
        # If there's an error, return the original text
        pass
    return text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    # Step 1: Tokenize the text into words and punctuation symbols
    tokens = text.split()

    # Step 2: Identify and extract the links from the text
    links = []
    for token in tokens:
        if token.startswith("http"):
            links.append(token)

    # Step 3: Add some attributes and linkify the extracted links
    for link in links:
        attributes = {
            "href": link,
            "target": "_blank",
            "rel": "noopener noreferrer"
        }
        html_tag = '<a {}>{}</a>'.format(" ".join('{}="{}"'.format(k, v) for k, v in attributes.items()), link)
        text = text.replace(link, html_tag)

    return text

