        # Return the NodeInfo data
        return data

    # Handle errors
    except ValueError as e:
        # Invalid input, return an empty dict
        return {}
    except requests.HTTPError as e:
        # Request failed, return an empty dict
        return {}
    except json.JSONDecodeError as e:
        # Invalid JSON response, return an empty dict
        return {}
    except Exception as e:
        # Unknown error, return an empty dict
        return {}

def get_nodeinfo_well_known_document(url: str, document_path: str = None) -> dict:
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Validate input parameters
    if not url:
        raise ValueError("Invalid URL")

    # Initialize output
    nodeinfo = {}

    # Extract hostname from URL
    hostname = urllib.parse.urlparse(url).hostname

    # Build NodeInfo document URL
    if document_path:
        nodeinfo_url = f"{url}/{document_path}"
    else:
        nodeinfo_url = f"{url}/.well-known/nodeinfo"

    # Fetch NodeInfo document
    try:
        response = requests.get(nodeinfo_url)
    except requests.exceptions.ConnectionError:
        raise Exception("Failed to retrieve NodeInfo document")

    # Parse NodeInfo document
    try:
        nodeinfo = response.json()
    except json.JSONDecodeError:
        raise Exception("Invalid NodeInfo document")

    # Validate NodeInfo document's JSON structure
    if not isinstance(nodeinfo, dict):
        raise Exception("Invalid NodeInfo document")

    # Store the NodeInfo document in the output dictionary
    nodeinfo["nodeinfo"] = {
        "hostname": hostname,
        "url": url,
        "document": nodeinfo_url,
    }

    return nodeinfo

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        from xml.dom import minidom
    except ImportError:
        from xml.etree import ElementTree
    try:
        from Crypto.Hash import SHA256
    except ImportError:
        from hashlib import sha256
    try:
        from Crypto.PublicKey import RSA
    except ImportError:
        from Cryptodome.PublicKey import RSA
    try:
        from Crypto.Signature import PKCS1_v1_5
    except ImportError:
        from Cryptodome.Signature import PKCS1_v1_5

    # Convert the public key to a RSA key object
    try:
        rsa_key = RSA.import_key(public_key)
    except ValueError:
        raise ValueError("Invalid public key")

    # Generate a SHA-256 hash of the XML document
    xml_doc = minidom.parseString(doc)
    xml_doc.normalize()
    xml_str = xml_doc.toprettyxml()
    xml_hash = SHA256.new(xml_str.encode("utf-8"))

    # Verify the digital signature
    signer = PKCS1_v1_5.new(rsa_key)
    digest = signer.verify(xml_hash, signature)

    # Check if the signature is valid
    if not digest:
        return False

    # Check if the signer's public key matches the public key we have
    if not rsa_key.compare_digest(digest):
        return False

    return True

def verify_relayable_signature(public_key, doc, signature):
    try:
        # Load the public key
        public_key = RSA.importKey(public_key)

        # Create a new XML Signature object
        signature = XMLSignature(doc)

        # Verify the signature
        if not signature.verify(public_key):
            raise InvalidSignatureError("Signature verification failed")
    except InvalidSignatureError:
        raise
    except Exception as e:
        raise RelayableSignatureVerificationError("Failed to verify relayable signature: {}".format(e))

def verify_relayable_signature(public_key, doc, signature):
