    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        xmlsec.verify(public_key, doc, signature)
    except Exception as e:
        return False
    return True

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from lxml import etree

    try:
        # Try to parse the document as JSON
        webfinger = json.loads(document)
        return webfinger
    except ValueError:
        # If it's not JSON, try parsing it as XRD
        root = etree.fromstring(document)
        webfinger = {}
        for link in root.findall('{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
            rel = link.get('rel')
            if rel:
                webfinger[rel] = link.get('href')
        return webfinger
    except Exception as e:
        raise ValueError(f"Invalid Diaspora webfinger document: {e}")

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        return {
            "subject": data["subject"],
            "links": [{"rel": link["rel"], "href": link["href"]} for link in data["links"]]
        }
    except json.JSONDecodeError:
        pass

    try:
        root = ET.fromstring(document)
        xrd = root.find(".//XRD", NS)
        subject = xrd.find("Subject", NS)
        links = xrd.findall("Link", NS)
        return {
            "subject": subject.text,
            "links": [{"rel": link.get("rel"), "href": link.get("href")} for link in links]
        }
    except ET.ParseError:
        raise ValueError("Invalid Diaspora webfinger document") from None

