def retrieve_diaspora_host_meta(host: str) -> XRD:
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: `XRD` instance
    """
    try:
        response = requests.get(f"https://{host}/.well-known/host-meta")
        response.raise_for_status()
        xml = ET.from_string(response.content)
        return XRD.from_xml(xml)
    except (requests.exceptions.RequestException, ET.ParseError) as e:
        raise DiasporaHostMetaRetrievalError(f"Failed to retrieve host-meta from {host}: {str(e)}") from e

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    try:
        response = requests.get(f"https://{host}/.well-known/host-meta.diaspora.xml")
        if response.status_code == 200:
            xrd = XRD()
            xrd.parse(response.content.decode())
            return xrd
        else:
            raise DiasporaHostMetaNotFound("Failed to retrieve host-meta document")
    except requests.exceptions.ConnectionError:
        raise DiasporaHostMetaNotFound("Failed to connect to remote host")
    except XMLSyntaxError:
        raise DiasporaHostMetaInvalid("Invalid XML in host-meta document")

