def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    try:
        if not isinstance(dic, dict):
            raise TypeError("dic must be a dictionary")
        if not keys:
            raise ValueError("keys must not be empty")
        current_dict = dic
        for sub_key in keys[:-1]:
            if sub_key not in current_dict:
                current_dict[sub_key] = {}
            current_dict = current_dict[sub_key]
        if key not in current_dict:
            current_dict[key] = val
        else:
            raise ValueError("key already exists")
    except ValueError as e:
        raise ValueError("invalid arguments") from e

def dict_insert(dic, val, key, *keys):
    """
    Insert a value for a nested key into a dictionary.

    :param dic: The dictionary to insert the value into.
    :param val: The value to insert.
    :param key: The first key in the chain of keys.
    :param keys: Any additional sub keys in the chain.
    """
    if not isinstance(dic, dict):
        raise TypeError("The first argument must be a dictionary.")
    if not keys:
        dic[key] = val
    else:
        if key not in dic:
            dic[key] = {}
        dict_insert(dic[key], val, keys[0], *keys[1:])

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    :param settings_dirs: The list of settings directories
    :param spec_option: The specific option to look for
    :return: A list of file names
    """
    # Validate inputs
    if not settings_dirs or not spec_option:
        raise ValueError("settings_dirs and spec_option must be provided")
    if not isinstance(settings_dirs, list):
        raise TypeError("settings_dirs must be a list")
    if not isinstance(spec_option, str):
        raise TypeError("spec_option must be a string")

    # Create a list of file names
    file_names = []
    for settings_dir in settings_dirs:
        for file in os.listdir(settings_dir):
            if file.endswith(".ini"):
                file_names.append(file)

    return file_names

def list_of_file_names(settings_dirs, spec_option):
    """
    Returns a list of file names in the given list of directories with the specified extension.
    :param settings_dirs: A list of directories to search for files.
    :param spec_option: The file extension to search for.
    :return: A list of file names with the specified extension.
    """
    file_names = []
    for directory in settings_dirs:
        for root, _, files in os.walk(directory):
            for file in files:
                if file.endswith(spec_option):
                    file_names.append(os.path.join(root, file))
    return file_names

