def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Args:
        parser_dict (dict): The parser dictionary containing the include directive.

    Returns:
        dict: The resolved include directive.

    Raises:
        ValueError: If the include directive is not valid.
        KeyError: If the include key is not found in the parser dictionary.

    """
    try:
        include_dict = parser_dict["includes"]
        resolved_includes = {}
        for key, value in include_dict.items():
            if isinstance(value, list):
                resolved_includes[key] = [self._resolve_include(v) for v in value]
            else:
                resolved_includes[key] = self._resolve_include(value)
        return resolved_includes
    except KeyError:
        raise ValueError("Include key not found in parser dictionary") from None

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    include_groups = parser_dict.get("include_groups", {})
    if not include_groups:
        return

    for group_name, group_dict in include_groups.items():
        try:
            self._apply_group(group_name, group_dict)
        except Exception as e:
            self.logger.error(
                f"Failed to apply group '{group_name}': {e}", exc_info=True
            )
    self.logger.debug("Successfully applied include groups")

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: A dictionary containing the resolved arguments' values.
    """
    spec = self.get_spec()
    defaults = {}
    for arg in spec.arguments:
        if arg.default is not None:
            defaults[arg.name] = arg.default
    return defaults

def get_spec_defaults(self):
    # Step 1: Extract arguments from the spec
    args = self.spec.args

    # Step 2: Check if there are any argument defaults
    if not args:
        return {}

    # Step 3: Resolve argument defaults from the spec
    defaults = {arg.name: arg.default for arg in args}

    # Step 4: Check if there are any missing defaults
    missing_defaults = set(defaults.keys()) - set(self.arguments.keys())
    if missing_defaults:
        raise ValueError(f"Missing default values for arguments: {missing_defaults}")

    # Step 5: Return the resolved defaults
    return defaults

def get_spec_defaults(self):
    # Step 1: Extract `arg` and `spec` from the method signature
    arg = self.arg
    spec = self.spec

    # Step 2: Initialize the return dictionary
    defaults = {}

    # Step 3: Iterate over the arguments in the spec
    for arg_name, arg_value in spec.items():
        # Step 3a: Check if the argument is a list
        if isinstance(arg_value, list):
            # Step 3ai: If it is a list, check if it is a list of dictionaries
            if all(isinstance(x, dict) for x in arg_value):
                # Step 3aia: If it is a list of dictionaries, extract the values
                # for the key `default`
                defaults[arg_name] = [x['default'] for x in arg_value]
            else:
                # Step 3aib: If it is not a list of dictionaries, set the value to `None`
                defaults[arg_name] = None
        else:
            # Step 3b: If the argument is not a list, set the value to `None`
            defaults[arg_name] = None

    # Step 4: Return the result
    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Args:
        self (Spec): The Spec object to resolve values for.

    Returns:
        dict: A dictionary containing the resolved values for the arguments.
    """

    spec = self.spec
    args = self.args
    kwargs = self.kwargs

    resolved_defaults = {}

    for arg in spec.arguments:
        if arg.name in kwargs:
            resolved_defaults[arg.name] = kwargs[arg.name]
        elif arg.default_value is not None:
            resolved_defaults[arg.name] = arg.default_value
        else:
            resolved_defaults[arg.name] = None

    return resolved_defaults

