def get_option_spec(self, command_name, argument_name):
    if not self.has_command(command_name):
        raise RuntimeError(f"Command {command_name} does not exist.")
    if not self.has_option(command_name, argument_name):
        raise RuntimeError(f"Option {argument_name} does not exist for command {command_name}.")
    option_spec = self.option_specs[command_name].get(argument_name)
    if option_spec is None:
        raise RuntimeError(f"Option {argument_name} does not have a specification for command {command_name}.")
    return option_spec

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. 

    :param command_name: The name of the command to get the option specification for
    :type command_name: str
    :param argument_name: The name of the option to get the specification for
    :type argument_name: str
    :return: The specification for the option
    :rtype: OptionSpec
    :raises ValueError: If the argument doesn't match the expected format
    """
    if not isinstance(argument_name, str):
        raise ValueError(f"Argument name must be a string, got {type(argument_name)}")
    if not isinstance(command_name, str):
        raise ValueError(f"Command name must be a string, got {type(command_name)}")

    option_spec = {}
    for option in self._option_maps[command_name]:
        if argument_name == option.name:
            option_spec = option.spec
            break

    if not option_spec:
        raise ValueError(f"Option with name '{argument_name}' not found for command '{command_name}'")

    return option_spec

