def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Check if the number of arguments is equal to 3
    if len(args) != 3:
        raise ValueError("Invalid number of arguments. Expected 3 arguments, but received {}.".format(len(args)))

    # Check if the first argument is a number
    if not isinstance(args[0], int):
        raise ValueError("Invalid argument type. Expected a number, but received {}.".format(type(args[0])))

    # Check if the second argument is a number
    if not isinstance(args[1], int):
        raise ValueError("Invalid argument type. Expected a number, but received {}.".format(type(args[1])))

    # Check if the third argument is a list
    if not isinstance(args[2], list):
        raise ValueError("Invalid argument type. Expected a list, but received {}.".format(type(args[2])))

    # Check if the first argument is less than or equal to the second argument
    if args[0] > args[1]:
        raise ValueError("Invalid argument value. The first argument must be less than or equal to the second argument.")

    # Check if the second argument is greater than or equal to the third argument
    if args[1] < args[2]:
        raise ValueError("Invalid argument value. The second argument must be greater than or equal to the third argument.")

    # Check if the third argument is a valid value
    if args[2] not in range(args[0], args[1] + 1):
        raise ValueError("Invalid argument value. The third argument must be a valid value between the first and second arguments.")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Step 1: Get minimum and maximum values from argument names
    min_values = [getattr(self, f"arg_{name}_min", None) for name in args]
    max_values = [getattr(self, f"arg_{name}_max", None) for name in args]

    # Step 2: Check if values are within bounds
    for name, value in zip(args, min_values, max_values):
        if value is not None and not (min_values[name] <= value <= max_values[name]):
            raise ValueError(f"Value of argument {name} must be between {min_values[name]} and {max_values[name]}.")

    # Step 3: Return True if all values are within bounds
    return all(min_values[name] <= value <= max_values[name] for name, value in zip(args, min_values, max_values))

