def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object representing the active workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: The playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: Dict. Passed to Ansible as extra-vars
    :param ansible_args: Dict of ansible-playbook arguments to plumb down directly to Ansible
    """

    import os
    import subprocess
    from infrared.core.utils.exceptions import AnsiblePlaybookError

    # Validate inputs
    if not isinstance(ir_workspace, infrared.core.workspace.Workspace):
        raise ValueError("ir_workspace must be an instance of infrared.core.workspace.Workspace")

    if not isinstance(ir_plugin, infrared.core.plugins.plugin.Plugin):
        raise ValueError("ir_plugin must be an instance of infrared.core.plugins.plugin.Plugin")

    if not isinstance(playbook_path, str):
        raise ValueError("playbook_path must be a string")

    if verbose is not None and not isinstance(verbose, int):
        raise ValueError("verbose must be an integer")

    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise ValueError("extra_vars must be a dict")

    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise ValueError("ansible_args must be a dict")

    # Setup the Ansible environment
    ansible_bin = os.path.join(ir_plugin.executable_dir, "ansible-playbook")
    ansible_base_dir = os.path.join(ir_workspace.temp_dir, "ansible")
    ansible_env = {
        "ANSIBLE_CONFIG": os.path.join(ansible_base_dir, "ansible.cfg"),
        "ANSIBLE_LIBRARY": os.path.join(ansible_base_dir, "modules"),
        "ANSIBLE_ROLES_PATH": os.path.join(ansible_base_dir, "roles"),
    }

    # Prepare the playbook arguments
    playbook_args = [ansible_bin, playbook_path]
    if verbose is not None:
        playbook_args.extend(["-" + str(verbose), "VERBOSE"])

    if extra_vars is not None:
        for key, value in extra_vars.items():
            playbook_args.extend(["--extra-vars", f"{key}={value}"])

    if ansible_args is not None:
        for key, value in ansible_args.items():
            playbook_args.extend([key, value])

    # Run the Ansible playbook
    try:
        subprocess.check_call(playbook_args, env=ansible_env)
    except subprocess.CalledProcessError as e:
        raise AnsiblePlaybookError(f"Ansible playbook failed with return code {e.returncode}")

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict"""
    try:
        # Check if workspace is valid
        if not ir_workspace:
            raise ValueError("Invalid workspace")

        # Check if plugin is valid
        if not ir_plugin:
            raise ValueError("Invalid plugin")

        # Build the ansible command
        cmd = ["ansible", "-i", ir_workspace.inventory_path, "--extra-vars", vars_dict]
        cmd.extend(cli_args)

        # Run the command and get the output
        output = subprocess.check_output(cmd, stderr=subprocess.STDOUT)

        # Return the ansible results
        return AnsibleResults(output.decode("utf-8"))
    except CalledProcessError as e:
        # If command failed, return error message
        return AnsibleResults(e.output.decode("utf-8"))

