        for key, value in values_dict.items():
            # Check if the argument is a boolean
            if str(value).lower() in ('true', 'false'):
                values_dict[key] = True if str(value).lower() == 'true' else False
            # Check if the argument is a number
            try:
                values_dict[key] = int(value)
            except ValueError:
                try:
                    values_dict[key] = float(value)
                except ValueError:
                    pass
    except Exception as e:
        print(f"Error: {e}")
        raise e

    for key, value in values_dict.items():
        # Convert any lists of strings to lists of integers
        if isinstance(value, list):
            try:
                values_dict[key] = list(map(int, value))
            except ValueError:
                pass

    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    try:
        # check if values_dict is a dictionary
        if not isinstance(values_dict, dict):
            raise ValueError("values_dict must be a dictionary")
        # check if parser_name is a string
        if not isinstance(parser_name, str):
            raise ValueError("parser_name must be a string")

        # convert values in values_dict to correct types
        for key, value in values_dict.items():
            values_dict[key] = self._convert_value(value, parser_name, key)

    except ValueError as e:
        print("Invalid values_dict or parser_name:", e)
        return None

    return values_dict

