    :return: A flatten dictionary contains the plugin's properties
    """

    # 1. Initialize the flatten dictionary
    flatten_dict = {}

    # 2. Read the plugin spec file
    spec_file = os.path.join(plugin_dir, "plugin.spec")
    with open(spec_file, "r") as f:
        spec_data = yaml.safe_load(f)

    # 3. Flatten the plugin spec data
    for key, value in spec_data.items():
        # 3a. Ignore the 'datasets' section
        if key == "datasets":
            continue

        # 3b. Handle composite types
        if isinstance(value, dict):
            for k, v in value.items():
                flatten_dict[f"{key}.{k}"] = v
        else:
            flatten_dict[key] = value

    return flatten_dict

